<?php require_once 'app.php';require_admin();$tables=['usuarios','transacoes','operacionais','investimentos','configuracoes'];$out="-- Backup ".date('c')."\n";foreach($tables as $t){$rows=db()->query("SELECT * FROM `$t`")->fetchAll();foreach($rows as $r){$cols=array_keys($r);$vals=array_map(fn($v)=>$v===null?'NULL':db()->quote((string)$v),array_values($r));$out.="INSERT INTO `$t` (`".implode('`,`',$cols)."`) VALUES (".implode(',',$vals).");\n";}}header('Content-Type: application/sql');header('Content-Disposition: attachment; filename=backup-'.date('Ymd-His').'.sql');echo $out;exit;